#!/bin/bash
set -e

# Influencer_22 image VQA, prompt set v3 (the 11 active prompts in vqa/prompt_test.ipynb).
# Runner: vqa/qwen3vl_img_vqa_parallel_v5.py on the main branch.
# Output: $OUTPUT_DIR/question_<N>/results.csv, N follows the order of QUESTIONS below.

# ===== Adjust these =====
IMAGE_DIR="/proj/berzelius-2024-409/users/dataset/influencer_22/images"
OUTPUT_DIR="/proj/berzelius-2024-409/users/x_liumi/Qwen3-VL/output/Qwen3-VL/output/influencer_22_v3"
MODEL_NAME="Qwen/Qwen3-VL-8B-Instruct"

NUM_GPUS=8
NNODES=1
RDZV_ENDPOINT="localhost:29500"

BATCH_SIZE=4
# Empty = use every image under IMAGE_DIR
NUM_SAMPLES=""

# Shuffle only balances the load across ranks; with NUM_SAMPLES empty all images are still processed
SHUFFLE=1
SEED=2026

# Match prompt_test.ipynb: MIN/MAX unset
MIN_PIXELS=""
MAX_PIXELS=""

# MIN_PIXELS=$((256*32*32))
# MAX_PIXELS=$((1280*32*32))

MAX_NEW_TOKENS=500
TEMPERATURE=0.6
TOP_P=0.9
TOP_K=50
REPETITION_PENALTY=1.05

DTYPE="bfloat16"
FLASH_ATTN2=0

QUESTIONS=(
  # Q1 Communicative intent
  "You are helping with a research annotation task on Instagram influencer images. Your task is to identify the PRIMARY communicative intent conveyed by the image — what the image is trying to do as an act of communication. Focus mainly on the visual content of the image, and use visible text only if it is clearly part of the image. Do not rely on outside knowledge about the person, brand, or event. Do not infer hidden motives unless there is strong visual evidence. Be conservative and choose the single best primary intent. If another intent is clearly present but secondary, record it as the secondary intent; otherwise set secondary_intent to null. Use the following 8 intent categories: advocative = the image advocates for a figure, idea, movement, cause, or value position through symbols, slogans, ribbons, protest imagery, political or social statements, memorials, or other stance-taking visuals. promotive = the image promotes a specific product, brand, service, event, release, or campaign, with the visual focus on the thing being promoted such as a product, poster, packaging, branded item, or event graphic; sponsored content, advertisements, product launches, and event posters fall here. exhibitionist_frontstage = the image presents the person as a polished, posed, front-stage self-image — appearance, styling, persona, status, or aspirational lifestyle constructed for the audience, including fashion portraits, glamour selfies, red carpet shots, posed solo shots, concert or performance moments, sports match scenes, and any polished depiction where the person as an image is the visual focus. exhibitionist_backstage = the image presents the person through a candid, everyday, or off-stage self-image — private life, family, pets, home, casual personal moments, behind-the-scenes preparation, candid working process, or routine daily activities; what defines this category is the backstage subject matter and candid framing, even if the image is well-shot. expressive = the image expresses emotion, attachment, admiration, gratitude, or affection toward an external entity, person, or group, such as tribute posts, anniversary celebrations of others, 'miss you' messages, or emotional appreciation posts. informative = the image delivers factual information, updates, announcements, explanations, or public messages, typically through designed graphics, infographics, text-heavy layouts, news-style cards, or announcement slides. entertainment = the image is designed to entertain through humor, memes, art, comics, jokes, or playful visual content where amusement is the main goal. interaction = the act of social connection or togetherness is the visual centerpiece of the image — group photos posed together, hugging, embracing, fan meet-and-greets, or collective celebration where the relational moment is the focus; the mere presence of other people in the frame does not qualify, the relational act itself must dominate the composition. The confidence field should reflect how certain the primary intent classification is based on visible evidence only. Add 2 to 3 sentences of justification for your choice. Return valid JSON only, with exactly these fields:{\"primary_intent\":\"...\", \"secondary_intent\":\"... or null\", \"confidence\":0.00, \"reasoning\":\"...\"}. Constraints: primary_intent must be one of [\"advocative\", \"promotive\", \"exhibitionist_frontstage\", \"exhibitionist_backstage\", \"expressive\", \"informative\", \"entertainment\", \"interaction\"]; secondary_intent must be one of the same labels or null; confidence must be between 0 and 1; reasoning should be 1 to 3 sentences."
  # Q2 Facial beautification (1-3 scale)
  "You are helping with a research annotation task on Instagram influencer images. Task: Evaluate the overall visible polish of the face of the most visually prominent person in the image. Use only visible evidence from the image. Do not use outside knowledge about the person, brand, or event. Focus only on the face or clearly visible facial region. If multiple faces are visible, focus on the single face that is most central, largest in the frame, and most clearly in focus. If no clear human face is visible, return null and explain briefly. Definition: Facial polish refers to the overall degree to which the face appears intentionally optimized, refined, or aesthetically enhanced beyond a plain natural capture. This includes any combination of visible makeup, skin smoothing, blemish reduction, retouching, filters, glam lighting, virtual beauty effects, or feature refinement. We do NOT distinguish between makeup and digital editing — both contribute to overall polish. Score on a 3-level scale: 1 = low polish — the face looks natural and largely unenhanced, with visible skin texture, pores, fine lines, or asymmetries, minimal or no makeup, and no obvious retouching or filter effects; 2 = medium polish — the face looks moderately polished, with noticeable makeup, mild smoothing or evening of skin tone, or modest stylistic enhancement, while still retaining some natural features; 3 = high polish — the face looks heavily refined or glam, with strong makeup, smoothed or airbrushed skin, clearly retouched appearance, glam lighting, or visible feature enhancement, giving an overall flawless or stylized look. Return valid JSON only in this format: {\"facial_polish\": 1 or \"null\", \"confidence\": 0.0, \"reasoning\": \"...\"}. Constraints: facial_polish must be an integer from 1 to 3, or null if no clear face is visible; confidence must be between 0 and 1; reasoning should be 1 to 2 sentences."
  # Q3 Facial beautification (1-5 scale)
  "You are helping with a research annotation task on Instagram influencer images. Task: Evaluate the overall visible polish of the face of the most visually prominent person in the image. Use only visible evidence from the image. Do not use outside knowledge about the person, brand, or event. Focus only on the face or clearly visible facial region. If multiple faces are visible, focus on the single face that is most central, largest in the frame, and most clearly in focus. If no clear human face is visible, return null and explain briefly. Definition: Facial polish refers to the overall degree to which the face appears visibly optimized, refined, or aesthetically enhanced beyond a plain natural capture. This includes any combination of visible makeup, skin smoothing, blemish reduction, retouching, filters, glam lighting, virtual beauty effects, or feature refinement. We do NOT distinguish between makeup and digital editing — both contribute to overall polish. Score facial_polish on a 5-level scale: 1 = none / very low polish — the face looks natural and largely unenhanced, with visible skin texture, pores, fine lines, asymmetries, minimal or no makeup, and no obvious retouching or filter effects. 2 = slight polish — the face shows minor visible polish, such as light makeup, mild skin evening, soft lighting, or subtle beautification, but the face still looks mostly natural and unretouched. 3 = moderate polish — the face looks clearly polished, with noticeable makeup, smoother or more even skin tone, mild retouching or filter effects, or modest glam lighting, while still retaining some natural facial texture and realistic features. 4 = strong polish — the face looks heavily refined or glam, with strong makeup, clearly smoothed skin, visible retouching or beauty-filter effects, enhanced facial features, or polished lighting that makes the face look noticeably optimized. 5 = very strong polish — the face looks extremely polished, airbrushed, or stylized, with very smooth or flawless skin, dominant makeup or beauty effects, strong feature refinement, heavy glam lighting, or an overall artificial, flawless, or highly edited appearance. Return valid JSON only in this format: {\"facial_polish\": 1 or \"null\", \"confidence\": 0.0, \"reasoning\": \"...\"}. Constraints: facial_polish must be an integer from 1 to 5, or null if no clear face is visible; confidence must be between 0 and 1; reasoning should be 1 to 2 sentences."
  # Q4 Global stylization or editing
  "You are helping with a research annotation task on Instagram influencer images. Task: Evaluate the overall degree of visible global or non-facial enhancement of the image, excluding face-specific beautification. Use only visible evidence from the image. Do not use outside knowledge about the person, brand, or event. Definition: Global or non-facial enhancement refers to the overall degree to which the image appears visibly treated, stylized, or polished beyond a plain natural capture, considering elements OTHER than the face. This includes visible filters, color grading, mood lighting, glossy commercial-grade polish, decorative overlays such as text or stickers or AR effects, dreamy or cinematic treatment, designed graphic elements, or any clearly added stylistic layer. Ordinary good photography alone (sharp focus, decent lighting, nice composition) does NOT count as enhancement — there must be visible signs of stylistic treatment or added elements beyond a plain capture. Important: Do NOT consider face-specific beautification (skin smoothing, makeup, facial retouching, feature reshaping) in this score. Score global_nonfacial_enhancement on a 5-level scale: 1 = none — image looks like a plain natural capture with natural color, natural lighting, and no visible filter, overlay, or stylistic treatment. 2 = slight — image shows minor enhancement such as light color adjustment, mild filter, or subtle stylistic touch, but overall still looks largely natural. 3 = moderate — image shows clearly visible enhancement such as a noticeable filter, color grading, mood lighting, light overlay or text, or polished editorial feel, while still feeling like a real-world photograph. 4 = strong — image is heavily enhanced, with strong filter, saturated or graded color, clear overlays, glossy commercial polish, or cinematic treatment that visibly departs from a plain capture. 5 = very strong — image is extremely stylized or designed, with dominant filter or color grading, multiple prominent overlays or graphic elements, designed aesthetic, or visual treatment that overwhelms any natural photographic feel. The reasoning field must briefly specify which type of enhancement is visible (e.g., color filter, text overlay, polish, lighting treatment, designed graphic element). Return valid JSON only in this format: {\"global_nonfacial_enhancement\": 1, \"confidence\": 0.0, \"reasoning\": \"...\"}. Constraints: global_nonfacial_enhancement must be an integer from 1 to 5; confidence must be between 0 and 1; reasoning should be 1 to 2 sentences and specify the type of enhancement visible."
  # Q5 Sexual suggestiveness
  "You are helping with a research annotation task on Instagram influencer images. Task: Evaluate the degree of perceived sexual suggestiveness in this image. Use only visible evidence from the image. Do not infer intentions, personality, or actual sexuality. Definition: Sexual suggestiveness refers to visible self-presentation cues that emphasize sensuality, sexualized body display, or sexualized appeal as a noticeable aspect of the image. Possible cues may include but are not limited to revealing clothing, suggestive pose, intimate camera angle, sensual facial expression, emphasis on sexualized body parts, or sexually charged styling. Scoring scale, based on how prominent sexualized appeal is within the overall presentation: 1 = none — presentation is neutral, professional, or focused on non-sexual aspects, with no visible sexualized appeal; 2 = minor — some hint of sensual or sexualized framing exists but is incidental and not a significant feature of the presentation; 3 = moderate — sexualized appeal is one identifiable feature of the presentation but does not dominate the overall impression; 4 = strong — sexualized appeal is a prominent and clearly intended feature of the presentation; 5 = dominant — sexualized appeal is the primary and overwhelming characteristic of the presentation. Return valid JSON only: {\"sexual_suggestiveness\": 0, \"confidence\": 0.0, \"reasoning\": \"...\"}. Constraints: sexual_suggestiveness must be an integer from 1 to 5; confidence must be between 0 and 1; reasoning should be 1 to 2 sentences."
  # Q6 Image-level emotion
  "You are helping with a research annotation task on Instagram influencer images. Task: Identify the primary image-level emotion conveyed by the image as a whole. Image-level emotion refers to the affective impression created by the full visual presentation of the image. Consider the overall image content, including setting, objects, facial expressions, body language, pose, color palette, lighting, composition, scenery, styling, visual design, and any clearly visible text that is part of the image. Use only evidence present in the image. Do not use outside knowledge about the person, brand, or event. Do not infer hidden motives or background context unless there is strong visual evidence. Categories: amusement = the image conveys humor, playfulness, fun, light-hearted entertainment, or something amusing. awe = the image conveys wonder, grandeur, vastness, beauty, admiration, inspiration, or a sense of being impressed. contentment = the image conveys calm satisfaction, comfort, peacefulness, relaxation, warmth, or quiet positive feeling. excitement = the image conveys high energy, enthusiasm, celebration, movement, intensity, or anticipation. anger = the image conveys anger, conflict, protest, hostility, confrontation, or strong negative opposition. disgust = the image conveys disgust, revulsion, unpleasantness, contamination, or strong aversion. fear = the image conveys threat, danger, anxiety, tension, insecurity, or fearfulness. sadness = the image conveys sorrow, loss, loneliness, heaviness, grief, or melancholy. neutral_or_unclear = the image does not convey a clear image-level emotion, or the emotional signal is too weak, mixed, or ambiguous to classify confidently. Rules: Select the single closest category based on the image as a whole. Do not classify only the facial expression of one person unless that expression dominates the image-level emotional impression. If no clear image-level emotion is conveyed, select neutral_or_unclear. Be conservative and choose neutral_or_unclear when the image is mainly informational, ordinary, or ambiguous. Return valid JSON only: {\"image_level_emotion\":\"...\", \"confidence\":0.0, \"reasoning\":\"...\"}. Constraints: image_level_emotion must be one of [\"amusement\", \"awe\", \"contentment\", \"excitement\", \"anger\", \"disgust\", \"fear\", \"sadness\", \"neutral_or_unclear\"]; confidence must be between 0 and 1; reasoning should be 1 to 2 sentences."
  # Q7 Topic
  "You are an image topic classification model. Analyze the provided image and choose the single most appropriate primary topic based on the overall image content, including visible objects, people, actions, setting, symbols, and any visible text that is part of the image. Do not infer context beyond what is clearly visible. Pick exactly ONE topic_id from the list below. Use \"others\" ONLY if none of the listed topics clearly apply. Focus on the dominant topical subject of the post, not the person’s occupation or celebrity identity alone. For example, a singer performing should usually be coded as \"entertainment\", an outfit- or modeling-centered post as \"fashion_style\", a meme or platform-centered post as \"social_media_internet\", a football or basketball scene as \"sports\", a NASA or space-exploration post as \"technology_science\", and a wildlife or landscape photography post as \"nature_environment\". Topics (topic_id: description): politics_public_affairs (e.g., politicians, elections, government, policy, activism, protests, or public issues). sports (e.g., football, basketball, cricket, athletes, matches, training, or sports events). entertainment (e.g., actors, singers, comedians, reality TV, movies, music, shows, entertainment companies, or pop culture events). fashion_style (e.g., fashion, outfits, modeling, beauty, styling, apparel, or sportswear when the main focus is clothing or appearance). social_media_internet (e.g., memes, internet humor, online trends, creator culture, platform-related content, social media references, screenshots, or creator tools). technology_science (e.g., science, technology, engineering, gadgets, research, space exploration, astronomy, or NASA-related science content). nature_environment (e.g., landscapes, wildlife, outdoor nature photography, conservation, pollution, climate, or environmental issues). health_fitness (e.g., exercise, gym, wellness, nutrition, healthcare, medicine, or public health). food_drink (e.g., meals, cooking, restaurants, recipes, beverages, or food culture). travel (e.g., tourism, destinations, landmarks, hotels, airports, transportation scenes, or travel experiences). business_brand (e.g., companies, products, advertising campaigns, entrepreneurship, markets, or commercial brand communication). art_culture (e.g., photography as art, museums, exhibitions, heritage, cultural events, or visual arts). education (e.g., schools, universities, studying, teaching, exams, or academic settings). religion (e.g., religious symbols, rituals, leaders, places of worship, or spiritual practice). lifestyle_everyday_life (e.g., ordinary daily life, casual personal moments, hanging out, home life, routine activities, mirror selfies, café scenes, street snapshots, or general lifestyle content when no more specific topic such as food, travel, fashion, or sports is dominant). others (e.g., provide a short best-fit label when none of the above clearly applies). Return JSON only in the following format, with no extra text: {\"topic\": \"<topic_id>\", \"confidence\": number, \"justification\": string, \"other_topic\": \"string or null\"} Constraints: confidence is a float between 0.0 and 1.0. justification must be one sentence. If topic is \"others\", provide a short best-fit label in \"other_topic\". If topic is not \"others\", set \"other_topic\" to null."
  # Q8 Person
  "Analyze the image and determine whether it contains one or more apparent real humans, depicted humans, or artificial human-like figures. Use only what is clearly visible in the image. Do not use outside knowledge about the person, brand, or event. Definitions: apparent_real_human = a photographed real person physically present in the scene. depicted_or_artificial_human = a human shown only as an image, illustration, poster, painting, screen display, advertisement, cartoon, avatar, statue, mannequin, doll, toy, CGI/synthetic figure, or other non-living representation. unclear = it is not visually clear whether the human-like figure is an apparent real human or a depiction/artificial figure. Do NOT count humans shown on posters, screens, paintings, advertisements, printed images, cartoons, illustrations, statues, mannequins, dolls, or other visual representations as apparent real humans. Count them under depicted_or_artificial_human instead. First, answer whether the image contains any apparent real humans. Then count how many apparent real humans are clearly visible. Also count how many depicted or artificial human-like figures are clearly visible. Identify the single most prominent human or human-like figure in the image, defined as the figure that is largest, clearest, most central, or most clearly the primary subject. This prominent figure may be an apparent real human, a depicted/artificial human, or unclear. For this one prominent figure only, provide the following information based only on what is clearly visible: \"prominent_person_type\" (apparent_real_human, depicted_or_artificial_human, unclear, or null (there is no human or human-like figure in this image)), \"gender\" (if visually apparent, otherwise null), \"age_range\" (approximate, otherwise null), \"outfit\", \"activity_or_pose\", \"facial_expression\", and \"interaction_with_others\" (if any). Assign a confidence score between 0 and 1 indicating how confident you are that you correctly classified the prominent figure and distinguished apparent real humans from depicted/artificial humans. Return valid JSON only in the following format:{\"has_apparent_real_human\": true, \"real_human_count\": 0, \"depicted_or_artificial_human_count\": 0, \"person\": {\"prominent_person_type\": \"apparent_real_human\", \"gender\": \"string or null\", \"age_range\": \"string or null\", \"outfit\": \"string or null\", \"activity_or_pose\": \"string or null\", \"facial_expression\": \"string or null\", \"interaction_with_others\": \"string or null\", \"confidence\": 0.0}}. Constraints: has_apparent_real_human must be true or false; real_human_count must count only apparent real humans; depicted_or_artificial_human_count must count only human depictions or artificial human-like figures; confidence must be between 0 and 1."
  # Q9 Attractiveness
  "Evaluate the most visually prominent person in the image. Use only visible evidence. If no clear human face is visible, return null for all face-dependent fields. First, assign an attractiveness score from 1 to 5 based on visible appearance only. Scale: 1 = very unattractive, 2 = unattractive, 3 = average, 4 = attractive, 5 = very attractive. Then provide a one-sentence justification for the attractiveness score. Second, assign a presentation_score from 1 to 5 indicating how visually polished and well-presented the person appears based on visible grooming, makeup if any, clothing coordination, and overall styling. Scale: 1 = very unpolished, 2 = below average presentation, 3 = average neat everyday appearance, 4 = good presentation, 5 = excellent presentation. Assign one confidence score between 0 and 1 for the overall judgment. Return valid JSON only in the following format: {\"attractive\": number | null, \"attractiveness_justification\": string | null, \"presentation_score\": number | null, \"confidence\": number}."
  # Q10 Image type
  "Classify the image format into exactly one label using the definitions below. Use only visible evidence from the image. Choose the single best matching label. If multiple labels seem possible, choose the label that describes the dominant visual format of the image. Use \"other\" only if no label reasonably fits. Labels: photo = a real-world camera photo of people, places, objects, food, fashion, travel, events, selfies, mirror selfies, lifestyle scenes, or product-in-context scenes. Minor text, stickers, emojis, filters, or small overlays do not change the label if the dominant format is still a real-world photo. screenshot = capture of an app, website, message, social media post, video call, or device interface showing UI elements such as menus, buttons, windows, bars, usernames, comments, or platform layout. text_document = text-dominant image such as a quote card, statement, announcement, apology, message, birthday greeting, motivational text, public statement, text-heavy slide, scanned or photographed document, form, page, letter, certificate, receipt, book page, handwritten note, or official-looking paper document. Use this label when the main format is text or a document-like page, and it is not primarily a screenshot, flyer, advertisement, or infographic. flyer_poster = event or announcement layout with clear practical information such as date, time, location, schedule, ticketing, registration, invitation, or call-to-action for attending or participating in an event. advertisement_graphic = promotional graphic for a product, brand, service, collection, sale, launch, discount, sponsorship, or commercial campaign, where the visual layout is designed mainly to advertise or sell something. infographic = visual explanation using charts, statistics, diagrams, step-by-step instructions, comparison tables, timelines, structured facts, or educational information. artwork_illustration = hand-drawn, painted, sketched, illustrated, comic-style, digitally illustrated, or synthesized artwork where the dominant format is not a real-world camera photo. meme = humorous, reaction-style, captioned, or template-based image where the main purpose is comedic or meme-like communication. other = none of the above clearly applies. Return valid JSON only: {\"image_type\": \"...\", \"confidence\": 0.0, \"reasoning\": \"...\"}. Constraints: image_type must be one of [\"photo\", \"screenshot\", \"text_card\", \"flyer_poster\", \"advertisement_graphic\", \"infographic\", \"artwork_illustration\", \"meme\", \"other\"]; confidence must be between 0 and 1; reasoning should be 1 sentence."
  # Q11 Image-level promotion
  "You are helping with a research annotation task on Instagram influencer images. Task: Determine the degree to which the image as a whole contains visible promotional content. Use only visible evidence from the image. Do not use outside knowledge about the person, brand, sponsorship status, or event. Do not infer that something is sponsored unless there is visible evidence in the image. Definition: Image-level promotion refers to whether the image visually presents, highlights, advertises, endorses, or directs attention toward a product, brand, service, event, media content, or other promotional object. Promotional content may be indicated by visible product packaging, logos, branded items, advertising text, discount codes, posters, event announcements, media release materials, product-centered composition, or a clearly promotional layout. Promotion type categories: none = no visible promotion, or any product/brand/event/media cue is only incidental, small, unclear, or not visually emphasized. product = the image promotes or highlights a product, brand, service, commercial object, app, clothing item, beauty product, food/drink item, venue, restaurant, hotel, or other marketable good/service. event = the image promotes or highlights an event, such as a concert, sports match, festival, exhibition, conference, public appearance, launch event, meet-and-greet, ceremony, or live performance. media = the image promotes or highlights media content, such as a TV show, film, music album, single, music video, book, podcast, magazine cover, YouTube video, streaming content, game, or other entertainment/media release. Important: Do not count something as promotional if a product, logo, brand, event, or media item is merely incidental, small, unclear, in the background, or not visually emphasized. Ordinary clothing, accessories, food, furniture, or everyday objects should not count as promotion unless they are clearly highlighted or presented as a focus of the image. Score image_level_promotion on a 3-level scale: 1 = no promotion — the image does not show clear promotional content. Any product, brand, event, or media cue is absent or merely incidental. 2 = possible or incidental promotion — the image contains some visible product, brand, event, or media cue, but it is secondary, ambiguous, weakly emphasized, or not clearly the focus of the image. 3 = clear promotion — the image clearly promotes or highlights a product, brand, service, event, or media content. Promotional content is visually evident and plays a central role in the image. Return valid JSON only: {\"image_level_promotion\": 1, \"promotion_type\": \"none\", \"promoted_entity\": null, \"reasoning\": \"...\", \"confidence\": 0.0}. Constraints: image_level_promotion must be an integer from 1 to 3; promotion_type must be one of [\"none\", \"product\", \"event\", \"media\"]; promoted_entity should name the visible product, brand, event, or media content if clearly identifiable from the image, otherwise null; confidence must be between 0 and 1; reasoning should be 1 to 2 sentences; visual_evidence must contain only concrete visible cues from the image."
)

SCRIPT="/proj/berzelius-2024-409/users/x_liumi/Qwen3-VL/vqa/qwen3vl_img_vqa_parallel_v5.py"

PIXEL_FLAGS=()
[[ -n "$MIN_PIXELS" ]] && PIXEL_FLAGS+=( --min_pixels "$MIN_PIXELS" )
[[ -n "$MAX_PIXELS" ]] && PIXEL_FLAGS+=( --max_pixels "$MAX_PIXELS" )

SHUFFLE_FLAG=()
[[ "$SHUFFLE" == "1" ]] && SHUFFLE_FLAG+=( --shuffle )

SEED_FLAG=()
# Only pass seed if shuffle is enabled and seed is provided
if [[ "$SHUFFLE" == "1" && -n "$SEED" ]]; then
  SEED_FLAG+=( --seed "$SEED" )
fi

NUM_SAMPLES_FLAG=()
[[ -n "$NUM_SAMPLES" ]] && NUM_SAMPLES_FLAG+=( --num_samples "$NUM_SAMPLES" )

FA2_FLAG=()
[[ "$FLASH_ATTN2" == "1" ]] && FA2_FLAG+=( --flash_attn2 )

torchrun \
  --nproc_per_node="$NUM_GPUS" \
  --nnodes="$NNODES" \
  --rdzv_backend=c10d \
  --rdzv_endpoint="$RDZV_ENDPOINT" \
  "$SCRIPT" \
    --image_dir "$IMAGE_DIR" \
    --output_dir "$OUTPUT_DIR" \
    --model_name "$MODEL_NAME" \
    --batch_size "$BATCH_SIZE" \
    --dtype "$DTYPE" \
    --max_new_tokens "$MAX_NEW_TOKENS" \
    --temperature "$TEMPERATURE" \
    --top_p "$TOP_P" \
    --top_k "$TOP_K" \
    --repetition_penalty "$REPETITION_PENALTY" \
    --output_confidence \
    "${PIXEL_FLAGS[@]}" \
    "${SHUFFLE_FLAG[@]}" \
    "${SEED_FLAG[@]}" \
    "${NUM_SAMPLES_FLAG[@]}" \
    "${FA2_FLAG[@]}" \
    --questions "${QUESTIONS[@]}"
